package dev.smokekitchen.cooking;

import com.google.gson.Gson;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class QualityAndTransferTest {
    @Test void cookedRiceTransitionKeepsHistoryButRecordsNewPotNeighbours(){var saved=new CookingBatch.Portion("rice",CookingBatch.Cut.WHOLE,1,true,false);saved.cooked=1.6;saved.charred=.2;saved.maximumTemperature=100;saved.lowHeatSeconds=20;saved.coveredCookingSeconds=25;saved.priorCounts.put("ginger",1);var target=new CookingBatch();target.temperature=130;target.oil=1;target.add("egg",CookingBatch.Cut.WHOLE,1,false,true);target.add("rice_cooked",CookingBatch.Cut.WHOLE,1,false,true);target.restorePortion(1,saved);var p=target.ingredients.get(1);assertEquals("rice_cooked",p.id);assertEquals(1.6,p.cooked);assertEquals(.2,p.charred);assertEquals(20,p.lowHeatSeconds);assertEquals(25,p.coveredCookingSeconds);assertFalse(p.needsWater);assertTrue(p.priorCounts.containsKey("egg"));assertFalse(p.priorCounts.containsKey("ginger"));assertTrue(p.temperatureOnAdd>110);}
    @Test void unrelatedOrUncookedIdentityCannotBorrowRiceHistory(){for(String from:new String[]{"rice","pork"}){var saved=new CookingBatch.Portion(from,CookingBatch.Cut.WHOLE,1,false,false);saved.cooked=from.equals("rice")?.5:2;saved.charred=.2;var target=new CookingBatch();target.add("rice_cooked",CookingBatch.Cut.WHOLE,1,false,true);target.restorePortion(0,saved);assertEquals(1,target.ingredients.getFirst().cooked);assertEquals(0,target.ingredients.getFirst().charred);}}
    @Test void dryFatRendersOnLowHeatInClayPotWithoutPretendingToBoil(){var b=new CookingBatch();b.method=CookingBatch.Method.BOIL;b.add("fat",CookingBatch.Cut.WHOLE,1,false,false);for(int i=0;i<70;i++)b.tick(1,false);assertTrue(b.ready());assertEquals(0,b.water);assertEquals(0,b.oil);assertEquals(0,b.ingredients.getFirst().charred);assertTrue(b.ingredients.getFirst().maximumTemperature<165);assertTrue(b.renderingFat());}
    @Test void fatWithWaterOrOtherFoodStillRequiresNormalWetCooking(){var b=new CookingBatch();b.method=CookingBatch.Method.BOIL;b.add("fat",CookingBatch.Cut.WHOLE,1,false,false);b.add("pork",CookingBatch.Cut.WHOLE,1,false,false);for(int i=0;i<70;i++)b.tick(1,false);assertFalse(b.ready());assertFalse(b.renderingFat());}
    private CookingBatch ready(){var b=new CookingBatch();b.oil=1;b.salt=1;for(int i=0;i<4;i++)b.add("egg",CookingBatch.Cut.DICE,1,false,true);for(int i=0;i<3;i++)b.stir();return b;}
    @Test void properForgottenAndSaltyCookingHaveDifferentQualityAndReasons(){var b=ready();assertEquals(3,b.quality());assertTrue(b.qualityReasons().isEmpty());b.stirs=0;assertEquals(2,b.quality());assertTrue(b.qualityReasons().contains("uneven"));b.salt=4;assertEquals(1,b.quality());assertTrue(b.qualityReasons().contains("salty"));}
    @Test void finalAdditionNeedsMixingAgainInsteadOfReusingOldClicks(){var b=ready();b.add("egg",CookingBatch.Cut.DICE,1,false,true);assertEquals(2,b.quality());b.stir();b.stir();b.stir();assertEquals(3,b.quality());}
    @Test void scorchedAndOvercookedFoodKeepSpecificExplanations(){var b=ready();b.ingredients.getFirst().charred=.3;assertEquals(1,b.quality());assertTrue(b.qualityReasons().contains("scorched"));b.ingredients.getFirst().cooked=3.3;assertTrue(b.qualityReasons().contains("overcooked"));b.ingredients.getFirst().charred=.8;assertEquals(0,b.quality());assertTrue(b.qualityReasons().contains("burnt"));}
    @Test void rawAndBlandAreDistinctFromBurnt(){var b=ready();b.salt=0;assertEquals(2,b.quality());assertTrue(b.qualityReasons().contains("bland"));b.ingredients.getFirst().cooked=.4;assertEquals(0,b.quality());assertTrue(b.qualityReasons().contains("raw"));assertFalse(b.qualityReasons().contains("burnt"));}
    @Test void moderatelySaltyFoodIsDifferentFromBalancedAndSeriouslyOversaltedFood(){var b=ready();b.salt=3;assertEquals(2,b.quality());assertTrue(b.qualityReasons().contains("strong"));assertFalse(b.qualityReasons().contains("salty"));}
    @Test void plainRicePorridgeBunsBreadAndPieDoNotRequireSavorySeasoning(){for(String id:new String[]{"rice","dough","dough_fermented","pie"}){var b=new CookingBatch();b.method=CookingBatch.Method.BAKE;b.add(id,CookingBatch.Cut.WHOLE,1,false,true);assertFalse(b.qualityReasons().contains("bland"));assertEquals(3,b.quality());}var soup=new CookingBatch();soup.method=CookingBatch.Method.BOIL;soup.add("dough",CookingBatch.Cut.SHRED,1,false,true);soup.add("cabbage",CookingBatch.Cut.DICE,1,false,true);assertTrue(soup.qualityReasons().contains("bland"));}
    @Test void aCorrectWarmTurnMakesEvenlyFriedFood(){var b=ready();b.method=CookingBatch.Method.FRY;assertEquals(2,b.quality());b.ingredients.forEach(p->p.cooked=.4);b.turn();b.ingredients.forEach(p->p.cooked=1);assertEquals(3,b.quality());}
    @Test void looseFoodRetainsItsHistoryAcrossSerializationAndAColdPot(){var source=ready();var p=source.ingredients.getFirst();p.cooked=1.7;p.charred=.2;p.maximumTemperature=190;p.turnedAfterSetting=true;p.cookedAtTurn=.4;p.marinatedSeconds=12;p.coveredCookingSeconds=20;p.lowHeatSeconds=15;p.caramelOnAdd=true;p.priorCounts.put("garlic",1);p.priorCooked.put("garlic",.3);
        var saved=new Gson().fromJson(new Gson().toJson(p),CookingBatch.Portion.class);var target=new CookingBatch();target.add("egg",CookingBatch.Cut.SLICE,1,false,false);target.restorePortion(0,saved);var q=target.ingredients.getFirst();assertEquals(1.7,q.cooked);assertEquals(.2,q.charred);assertEquals(190,target.maximumFoodTemperature);assertTrue(q.turnedAfterSetting&&q.caramelOnAdd);assertEquals(.4,q.cookedAtTurn);assertEquals(12,q.marinatedSeconds);assertEquals(20,q.coveredCookingSeconds);assertEquals(15,q.lowHeatSeconds);assertTrue(q.priorCooked.isEmpty());assertEquals(20,q.temperatureOnAdd);assertEquals(CookingBatch.Cut.SLICE,q.cut);assertEquals(0,target.oil);assertEquals(0,target.salt);}
    @Test void oldBatchHistoryMigratesConservativelyAndClearsWhenFoodLeaves(){var b=ready();b.maximumFoodTemperature=180;b.ingredients.forEach(p->p.maximumTemperature=0);b.normalize();assertTrue(b.ingredients.stream().allMatch(p->p.maximumTemperature==180));b.ingredients.clear();b.refreshTemperatureHistory();assertEquals(0,b.maximumFoodTemperature);}
    @Test void historyIsBoundedEvenWhenOldTemperatureIsMalformed(){var b=ready();b.temperature=Double.NaN;b.maximumFoodTemperature=Double.POSITIVE_INFINITY;b.ingredients.getFirst().maximumTemperature=0;b.normalize();assertTrue(Double.isFinite(b.ingredients.getFirst().maximumTemperature));assertEquals(20,b.temperature);}
    @Test void splitTransfersConserveAllSixSeasoningsThroughRepeatedSerializedRoundTrips(){
        var b=ready();b.salt=4;b.soy=2;b.vinegar=1;b.sugar=3;b.spice=2;
        for(int round=0;round<8;round++){
            var target=new CookingBatch();
            while(!b.ingredients.isEmpty()){var p=b.removePortion(b.ingredients.size()-1);p=new Gson().fromJson(new Gson().toJson(p),CookingBatch.Portion.class);target.add(p.id,p.cut,p.resistance,p.needsWater,false);target.restorePortion(target.ingredients.size()-1,p);}
            assertEquals(0,b.salt,1e-9);assertEquals(4,target.salt,1e-9);assertEquals(1,target.oil,1e-9);assertEquals(2,target.soy,1e-9);assertEquals(1,target.vinegar,1e-9);assertEquals(3,target.sugar,1e-9);assertEquals(2,target.spice,1e-9);
            target.stir();target.stir();target.stir();assertEquals(1,target.quality());assertTrue(target.qualityReasons().contains("salty"));b=target;
        }
    }
    @Test void onePortionCarriesOnlyItsShareAndPreviewDoesNotConsumeAnything(){var b=ready();b.salt=4;var preview=b.portionBatch(3);assertEquals(1,preview.salt);assertEquals(4,b.salt);var p=b.removePortion(3);assertEquals(1,p.seasonings.get("salt"));assertEquals(.25,p.seasonings.get("oil"));assertEquals(3,b.salt);assertEquals(.75,b.oil);}
    @Test void salinityCanBeDilutedButScorchingAndOldSourQualityCannotBeErased(){var b=ready();b.salt=4;var p=b.removePortion(0);var target=new CookingBatch();target.add("egg",p.cut,1,false,true);target.restorePortion(0,p);target.stir();target.stir();target.stir();assertEquals(1,target.quality());target.add("egg",p.cut,1,false,true);target.stir();target.stir();target.stir();assertEquals(3,target.quality());target.ingredients.getFirst().charred=.3;assertEquals(1,target.quality());target.ingredients.getFirst().charred=0;target.ingredients.getFirst().qualityLimit=1;target.ingredients.getFirst().inheritedReasons.add("strong");assertEquals(1,target.quality());}
    @Test void oldIntegerSeasoningSavesRemainReadableAndMissingTransferFieldsAreNeutral(){var b=new Gson().fromJson("{\"salt\":4,\"oil\":1,\"ingredients\":[{\"id\":\"egg\",\"cooked\":1,\"cut\":\"DICE\",\"resistance\":1}]}",CookingBatch.class);b.normalize();assertEquals(4,b.salt);assertNull(b.ingredients.getFirst().qualityLimit);assertNotNull(b.ingredients.getFirst().seasonings);}
    @Test void individualCookedQualityIsNotDowngradedByAnotherRawPortion(){var b=ready();b.ingredients.getLast().cooked=0;assertEquals(0,b.quality());assertEquals(3,b.portionBatch(0).quality());}
    @Test void malformedSharesCannotImportNaNOrNegativeQuantities(){var b=new CookingBatch();b.add("egg",CookingBatch.Cut.DICE,1,false,true);var p=new CookingBatch.Portion("egg",CookingBatch.Cut.DICE,1,false,true);p.seasonings.put("salt",Double.NaN);p.seasonings.put("oil",-1d);b.restorePortion(0,p);assertEquals(0,b.salt);assertEquals(0,b.oil);}
}
